function getTranslationDictionaries() {
	return [pageTranslations, additionalPageTranslations, missingPageTranslations, authorityTranslations, translations];
}

function getOriginalText(value) {
	for (const dictionaries of getTranslationDictionaries()) {
		for (const dictionary of Object.values(dictionaries)) {
			const original = Object.keys(dictionary).find((key) => dictionary[key] === value);
			if (original) return original;
		}
	}
	return value;
}

function translateRenderedText(language) {
	const root = document.getElementById("root");
	if (!root) return;
	const dictionary = { ...pageTranslations[language], ...additionalPageTranslations[language], ...missingPageTranslations[language], ...authorityTranslations[language], ...benefitsTranslations[language], ...reportedTranslations[language], ...translations[language] };
	const walker = document.createTreeWalker(root, 4);
	let node;
	while ((node = walker.nextNode())) {
		const parent = node.parentElement;
		if (!parent || parent.closest("script, style")) continue;
		const original = getOriginalText(node.nodeValue);
		const trimmed = original.trim();
		if (!trimmed) continue;
		node.nodeValue = original.replace(trimmed, dictionary[trimmed] || trimmed);
	}
}

function translateRenderedPage(language) {
	const dictionary = pageTranslations[language] || {};
	const root = document.getElementById("root");
	if (!root) return;
	const translate = (value) => dictionary[value] || translations[language]?.[value] || value;
	const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
	let node;
	while ((node = walker.nextNode())) {
		if (!node.parentElement || ["SCRIPT", "STYLE"].includes(node.parentElement.tagName)) continue;
		const original = node.__potencializaOriginal ?? node.nodeValue;
		node.__potencializaOriginal = original;
		const trimmed = original.trim();
		if (!trimmed) continue;
		node.nodeValue = original.replace(trimmed, translate(trimmed));
	}
	root.querySelectorAll("[placeholder], [aria-label], [title]").forEach((element) => {
		["placeholder", "aria-label", "title"].forEach((attribute) => {
			const value = element.getAttribute(attribute);
			if (!value) return;
			const key = `potencializaOriginal${attribute}`;
			const original = element.dataset[key] || value;
			element.dataset[key] = original;
			element.setAttribute(attribute, translate(original));
		});
	});
}

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
	const [language, setLanguage] = useState(() => {
		const savedLanguage = localStorage.getItem("potencializa-language");
		return savedLanguage && languages[savedLanguage] ? savedLanguage : "pt";
	});

	useEffect(() => {
		localStorage.setItem("potencializa-language", language);
		document.documentElement.lang = languages[language].locale;
		const frame = requestAnimationFrame(() => translateRenderedText(language));
		return () => cancelAnimationFrame(frame);
	}, [language]);

	const value = useMemo(() => ({
		language,
		setLanguage,
		languages,
		t: (text) => translations[language]?.[text] || reportedTranslations[language]?.[text] || missingPageTranslations[language]?.[text] || additionalPageTranslations[language]?.[text] || authorityTranslations[language]?.[text] || benefitsTranslations[language]?.[text] || pageTranslations[language]?.[text] || text,
	}), [language]);

	return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
	const context = useContext(LanguageContext);
	if (!context) throw new Error("useLanguage must be used inside LanguageProvider");
	return context;
}
